def ser(e):
    return str(e.get("serial","")).lstrip("#")

srcs={}
for b in ["003","006","007"]:
    for e in json.load(open(f"batches_full/batch_src_{b}.json",encoding="utf-8")):
        srcs[str(e["serial"])] = e

allserial=list(RECOMMENDS.keys())
fails={}
for s in allserial:
    rec=RECOMMENDS[s]
    e=srcs[s]
    tmp=dict(e); tmp["recommend"]=rec
    iss=validate(tmp, skip={"R10"})
    if iss:
        fails[s]=iss
    else:
        fp=os.path.join(HERE,"drafts_v4",f"draft_{s}.json")
        json.dump({"serial":s,"recommend":rec}, open(fp,"w",encoding="utf-8"), ensure_ascii=False, indent=2)

print(f"自我校验(跳过R10) {len(allserial)} 家 | 通过 {len(allserial)-len(fails)} | 未过 {len(fails)}")
for s,iss in fails.items():
    print(f"  {s}: {iss}")
